DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='c4g_opportunity_tenant_owner') THEN CREATE ROLE c4g_opportunity_tenant_owner NOLOGIN NOINHERIT; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='c4g_opportunity_tenant_runtime') THEN CREATE ROLE c4g_opportunity_tenant_runtime NOLOGIN NOINHERIT; END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='c4g_opportunity_tenant_migrator') THEN CREATE ROLE c4g_opportunity_tenant_migrator NOLOGIN NOINHERIT; END IF;
END $$;
GRANT c4g_opportunity_tenant_owner TO c4g_opportunity_tenant_migrator;
GRANT USAGE ON SCHEMA document_storage TO c4g_opportunity_tenant_owner;
GRANT REFERENCES (organization_id,document_id,version_id) ON document_storage.document_version TO c4g_opportunity_tenant_owner;
CREATE SCHEMA opportunity_catalog AUTHORIZATION c4g_opportunity_tenant_owner;
REVOKE ALL ON SCHEMA opportunity_catalog FROM PUBLIC;
GRANT USAGE ON SCHEMA opportunity_catalog TO c4g_opportunity_tenant_runtime;
SET ROLE c4g_opportunity_tenant_owner;
CREATE TABLE opportunity_catalog.opportunity (
 organization_id uuid NOT NULL, opportunity_id uuid NOT NULL, current_revision_id uuid NOT NULL, revision_number integer NOT NULL CHECK(revision_number>0), row_version bigint NOT NULL CHECK(row_version>0), lifecycle_state text NOT NULL CHECK(lifecycle_state IN ('DRAFT','ACTIVE','STALE','ARCHIVED')), validation_state text NOT NULL CHECK(validation_state IN ('PENDING_REVIEW','VALIDATED_MANUAL','CONFLICT')),
 title text NOT NULL CHECK(length(title) BETWEEN 1 AND 300), funder_name text NOT NULL CHECK(length(funder_name) BETWEEN 1 AND 200), programme_name text, call_reference text, official_url text, opening_date date, closing_date date,
 quality_score smallint NOT NULL CHECK(quality_score BETWEEN 0 AND 100), quality_bucket text NOT NULL CHECK(quality_bucket IN ('LOW','MEDIUM','HIGH','COMPLETE')), content_digest char(64) NOT NULL CHECK(content_digest ~ '^[a-f0-9]{64}$'), normalization_version text NOT NULL CHECK(normalization_version='opportunity-normalization-v1'), quality_rule_version text NOT NULL CHECK(quality_rule_version='opportunity-quality-v1'), created_at timestamptz NOT NULL DEFAULT transaction_timestamp(), updated_at timestamptz NOT NULL DEFAULT transaction_timestamp(), archived_at timestamptz,
 PRIMARY KEY(organization_id,opportunity_id), UNIQUE(opportunity_id), CHECK(closing_date IS NULL OR opening_date IS NULL OR closing_date>=opening_date)
);
CREATE TABLE opportunity_catalog.revision (organization_id uuid NOT NULL, revision_id uuid NOT NULL, opportunity_id uuid NOT NULL, revision_number integer NOT NULL CHECK(revision_number>0), row_version bigint NOT NULL CHECK(row_version>0), snapshot jsonb NOT NULL CHECK(jsonb_typeof(snapshot)='object'), normalized_projection jsonb NOT NULL CHECK(jsonb_typeof(normalized_projection)='object'), quality_projection jsonb NOT NULL CHECK(jsonb_typeof(quality_projection)='object'), content_digest char(64) NOT NULL CHECK(content_digest ~ '^[a-f0-9]{64}$'), created_at timestamptz NOT NULL DEFAULT transaction_timestamp(), PRIMARY KEY(organization_id,revision_id), UNIQUE(revision_id), UNIQUE(organization_id,opportunity_id,revision_number), UNIQUE(organization_id,opportunity_id,row_version), FOREIGN KEY(organization_id,opportunity_id) REFERENCES opportunity_catalog.opportunity(organization_id,opportunity_id));
ALTER TABLE opportunity_catalog.opportunity ADD CONSTRAINT opportunity_current_revision_fk FOREIGN KEY(organization_id,current_revision_id) REFERENCES opportunity_catalog.revision(organization_id,revision_id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE opportunity_catalog.provenance (organization_id uuid NOT NULL, provenance_id uuid NOT NULL, opportunity_id uuid NOT NULL, revision_id uuid NOT NULL, source_type text NOT NULL CHECK(source_type='ORGANIZATION_MANUAL'), source_namespace text NOT NULL CHECK(source_namespace ~ '^[A-Z][A-Z0-9_]{0,63}$'), external_identifier text, normalized_external_identifier text, source_url text, observed_at timestamptz NOT NULL, recorded_at timestamptz NOT NULL DEFAULT transaction_timestamp(), recorded_by_actor_type text NOT NULL CHECK(recorded_by_actor_type IN ('HUMAN','SERVICE')), recorded_by_actor_reference text NOT NULL CHECK(length(recorded_by_actor_reference) BETWEEN 1 AND 128), source_digest char(64) NOT NULL CHECK(source_digest ~ '^[a-f0-9]{64}$'), PRIMARY KEY(organization_id,provenance_id), FOREIGN KEY(organization_id,opportunity_id) REFERENCES opportunity_catalog.opportunity(organization_id,opportunity_id), FOREIGN KEY(organization_id,revision_id) REFERENCES opportunity_catalog.revision(organization_id,revision_id));
CREATE TABLE opportunity_catalog.organization_opportunity (organization_id uuid NOT NULL, relation_id uuid NOT NULL, private_opportunity_id uuid, central_opportunity_id uuid, central_revision_id uuid, central_snapshot_digest char(64), display_title text, created_at timestamptz NOT NULL DEFAULT transaction_timestamp(), PRIMARY KEY(organization_id,relation_id), CHECK((private_opportunity_id IS NOT NULL)::int+(central_opportunity_id IS NOT NULL)::int=1), CHECK((central_opportunity_id IS NULL AND central_revision_id IS NULL AND central_snapshot_digest IS NULL) OR (central_opportunity_id IS NOT NULL AND central_revision_id IS NOT NULL AND central_snapshot_digest ~ '^[a-f0-9]{64}$')), FOREIGN KEY(organization_id,private_opportunity_id) REFERENCES opportunity_catalog.opportunity(organization_id,opportunity_id));
CREATE TABLE opportunity_catalog.idempotency_record (organization_id uuid NOT NULL, operation text NOT NULL CHECK(operation IN ('CREATE','UPDATE','ARCHIVE','RESTORE','PROVENANCE_APPEND','QUALITY_RECOMPUTE','DUPLICATE_RECORD','DOCUMENT_BIND')), request_id text NOT NULL CHECK(length(request_id) BETWEEN 8 AND 128), request_digest char(64) NOT NULL CHECK(request_digest ~ '^[a-f0-9]{64}$'), opportunity_id uuid NOT NULL, revision_id uuid, result_projection jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT transaction_timestamp(), PRIMARY KEY(organization_id,operation,request_id));
CREATE TABLE opportunity_catalog.duplicate_candidate (organization_id uuid NOT NULL, left_opportunity_id uuid NOT NULL, right_opportunity_id uuid NOT NULL, left_revision_id uuid NOT NULL, right_revision_id uuid NOT NULL, rule_version text NOT NULL CHECK(rule_version='opportunity-deduplication-v1'), classification text NOT NULL CHECK(classification IN ('EXACT','POSSIBLE','DISTINCT')), reason_codes text[] NOT NULL CHECK(cardinality(reason_codes) BETWEEN 1 AND 16), evidence_fields text[] NOT NULL CHECK(cardinality(evidence_fields)<=16), left_digest char(64) NOT NULL, right_digest char(64) NOT NULL, reconciliation_state text NOT NULL DEFAULT 'CURRENT' CHECK(reconciliation_state IN ('CURRENT','STALE','REQUIRES_RECONCILIATION')), observed_at timestamptz NOT NULL DEFAULT transaction_timestamp(), CHECK(left_opportunity_id<right_opportunity_id), PRIMARY KEY(organization_id,left_opportunity_id,right_opportunity_id,rule_version));
CREATE TABLE opportunity_catalog.opportunity_document_binding (
 organization_id uuid NOT NULL,
 binding_id uuid NOT NULL,
 opportunity_id uuid NOT NULL,
 document_id uuid NOT NULL,
 document_version_id uuid NOT NULL,
 opportunity_revision_id uuid NOT NULL,
 expected_opportunity_row_version bigint NOT NULL CHECK(expected_opportunity_row_version>0),
 idempotency_key text NOT NULL CHECK(length(idempotency_key) BETWEEN 8 AND 128),
 request_digest char(64) NOT NULL CHECK(request_digest ~ '^[a-f0-9]{64}$'),
 row_version bigint NOT NULL DEFAULT 1 CHECK(row_version=1),
 created_by_actor_type text NOT NULL CHECK(created_by_actor_type IN ('HUMAN','SERVICE')),
 created_by_actor_reference text NOT NULL CHECK(length(created_by_actor_reference) BETWEEN 1 AND 128),
 created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),
 archived_at timestamptz CHECK(archived_at IS NULL),
 PRIMARY KEY(organization_id,binding_id),
 UNIQUE(binding_id),
 UNIQUE(organization_id,opportunity_id,document_id,document_version_id),
 UNIQUE(organization_id,idempotency_key),
 FOREIGN KEY(organization_id,opportunity_id) REFERENCES opportunity_catalog.opportunity(organization_id,opportunity_id),
 FOREIGN KEY(organization_id,opportunity_revision_id) REFERENCES opportunity_catalog.revision(organization_id,revision_id),
 FOREIGN KEY(organization_id,document_id,document_version_id) REFERENCES document_storage.document_version(organization_id,document_id,version_id)
);
CREATE INDEX opportunity_updated_keyset ON opportunity_catalog.opportunity(organization_id,updated_at DESC,opportunity_id DESC); CREATE INDEX opportunity_closing_keyset ON opportunity_catalog.opportunity(organization_id,closing_date,opportunity_id); CREATE INDEX opportunity_title_keyset ON opportunity_catalog.opportunity(organization_id,title,opportunity_id); CREATE INDEX provenance_opportunity_revision ON opportunity_catalog.provenance(organization_id,opportunity_id,revision_id); CREATE INDEX provenance_source_identity ON opportunity_catalog.provenance(organization_id,source_namespace,normalized_external_identifier);
CREATE INDEX opportunity_block_content_digest ON opportunity_catalog.opportunity(organization_id,content_digest,opportunity_id);
CREATE INDEX opportunity_block_opening_date ON opportunity_catalog.opportunity(organization_id,opening_date,opportunity_id) WHERE opening_date IS NOT NULL;
CREATE INDEX opportunity_block_closing_date ON opportunity_catalog.opportunity(organization_id,closing_date,opportunity_id) WHERE closing_date IS NOT NULL;
CREATE INDEX revision_block_programme_reference ON opportunity_catalog.revision(organization_id,(normalized_projection->>'programmeName'),(normalized_projection->>'callReference'),opportunity_id) WHERE normalized_projection->>'programmeName' IS NOT NULL AND normalized_projection->>'callReference' IS NOT NULL;
CREATE INDEX revision_block_official_url ON opportunity_catalog.revision(organization_id,(normalized_projection->>'officialUrl'),opportunity_id) WHERE normalized_projection->>'officialUrl' IS NOT NULL;
CREATE INDEX revision_block_title ON opportunity_catalog.revision(organization_id,(normalized_projection->>'title'),opportunity_id);
CREATE INDEX revision_block_funder ON opportunity_catalog.revision(organization_id,(normalized_projection->>'funderName'),opportunity_id);
CREATE INDEX revision_block_programme ON opportunity_catalog.revision(organization_id,(normalized_projection->>'programmeName'),opportunity_id) WHERE normalized_projection->>'programmeName' IS NOT NULL;
CREATE INDEX revision_block_thematic_codes ON opportunity_catalog.revision USING gin((normalized_projection->'thematicCodes'));
CREATE INDEX revision_block_territory_codes ON opportunity_catalog.revision USING gin((normalized_projection->'territoryCodes'));
CREATE INDEX opportunity_document_by_opportunity ON opportunity_catalog.opportunity_document_binding(organization_id,opportunity_id,created_at,binding_id);
CREATE INDEX opportunity_document_by_document ON opportunity_catalog.opportunity_document_binding(organization_id,document_id,document_version_id);
CREATE FUNCTION opportunity_catalog.reject_history_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'OPPORTUNITY_HISTORY_IMMUTABLE'; END $$;
CREATE TRIGGER revision_immutable BEFORE UPDATE OR DELETE ON opportunity_catalog.revision FOR EACH ROW EXECUTE FUNCTION opportunity_catalog.reject_history_mutation(); CREATE TRIGGER provenance_immutable BEFORE UPDATE OR DELETE ON opportunity_catalog.provenance FOR EACH ROW EXECUTE FUNCTION opportunity_catalog.reject_history_mutation();
CREATE TRIGGER opportunity_document_binding_immutable BEFORE UPDATE OR DELETE ON opportunity_catalog.opportunity_document_binding FOR EACH ROW EXECUTE FUNCTION opportunity_catalog.reject_history_mutation();
ALTER TABLE opportunity_catalog.opportunity ENABLE ROW LEVEL SECURITY; ALTER TABLE opportunity_catalog.revision ENABLE ROW LEVEL SECURITY; ALTER TABLE opportunity_catalog.provenance ENABLE ROW LEVEL SECURITY; ALTER TABLE opportunity_catalog.organization_opportunity ENABLE ROW LEVEL SECURITY; ALTER TABLE opportunity_catalog.idempotency_record ENABLE ROW LEVEL SECURITY; ALTER TABLE opportunity_catalog.duplicate_candidate ENABLE ROW LEVEL SECURITY; ALTER TABLE opportunity_catalog.opportunity_document_binding ENABLE ROW LEVEL SECURITY;
CREATE POLICY opportunity_isolation ON opportunity_catalog.opportunity USING(organization_id=current_setting('app.organization_id',true)::uuid) WITH CHECK(organization_id=current_setting('app.organization_id',true)::uuid);
CREATE POLICY revision_isolation ON opportunity_catalog.revision USING(organization_id=current_setting('app.organization_id',true)::uuid) WITH CHECK(organization_id=current_setting('app.organization_id',true)::uuid);
CREATE POLICY provenance_isolation ON opportunity_catalog.provenance USING(organization_id=current_setting('app.organization_id',true)::uuid) WITH CHECK(organization_id=current_setting('app.organization_id',true)::uuid);
CREATE POLICY relation_isolation ON opportunity_catalog.organization_opportunity USING(organization_id=current_setting('app.organization_id',true)::uuid) WITH CHECK(organization_id=current_setting('app.organization_id',true)::uuid);
CREATE POLICY idempotency_isolation ON opportunity_catalog.idempotency_record USING(organization_id=current_setting('app.organization_id',true)::uuid) WITH CHECK(organization_id=current_setting('app.organization_id',true)::uuid);
CREATE POLICY duplicate_isolation ON opportunity_catalog.duplicate_candidate USING(organization_id=current_setting('app.organization_id',true)::uuid) WITH CHECK(organization_id=current_setting('app.organization_id',true)::uuid);
CREATE POLICY opportunity_document_binding_isolation ON opportunity_catalog.opportunity_document_binding USING(organization_id=current_setting('app.organization_id',true)::uuid) WITH CHECK(organization_id=current_setting('app.organization_id',true)::uuid);
GRANT SELECT,INSERT,UPDATE ON opportunity_catalog.opportunity TO c4g_opportunity_tenant_runtime; GRANT SELECT,INSERT ON opportunity_catalog.revision,opportunity_catalog.provenance,opportunity_catalog.organization_opportunity,opportunity_catalog.idempotency_record,opportunity_catalog.duplicate_candidate,opportunity_catalog.opportunity_document_binding TO c4g_opportunity_tenant_runtime; GRANT UPDATE ON opportunity_catalog.duplicate_candidate TO c4g_opportunity_tenant_runtime; REVOKE UPDATE,DELETE,TRUNCATE ON opportunity_catalog.opportunity_document_binding FROM c4g_opportunity_tenant_runtime; REVOKE DELETE,TRUNCATE ON ALL TABLES IN SCHEMA opportunity_catalog FROM c4g_opportunity_tenant_runtime;
RESET ROLE;
GRANT USAGE ON SCHEMA document_storage TO c4g_opportunity_tenant_runtime;
GRANT SELECT(organization_id,document_id,version_id,state,scan_state,lock_version) ON document_storage.document_version TO c4g_opportunity_tenant_runtime;
GRANT USAGE ON SCHEMA audit TO c4g_opportunity_tenant_runtime; GRANT EXECUTE ON FUNCTION audit.prepare_append_v1(uuid,text) TO c4g_opportunity_tenant_runtime; GRANT EXECUTE ON FUNCTION audit.append_event_v1(uuid,text,text,integer,text,text,audit.ledger_location,uuid,uuid,audit.actor_type,text,text,text,bigint,timestamptz,timestamptz,uuid,uuid,text,text,text,text,jsonb) TO c4g_opportunity_tenant_runtime;
ALTER TABLE audit.event_identity DROP CONSTRAINT event_identity_event_code_check; ALTER TABLE audit.event_identity ADD CONSTRAINT event_identity_event_code_check CHECK(event_code IN ('AUTHORIZATION_ALLOWED','AUTHORIZATION_DENIED','AUTHORIZATION_POLICY_INVALID','AUTHORIZATION_MFA_REQUIRED','AUTHORIZATION_VERSION_ADVANCED','GRANT_CHANGED','PROFILE_CHANGED','SOD_CHANGED','SENSITIVE_ACTION_ALLOWED','SUPPORT_GRANTED','SUPPORT_STARTED','SUPPORT_USED','SUPPORT_REVOKED','SUPPORT_EXPIRED','SERVICE_JOB_DISPATCHED','SERVICE_JOB_COMPLETED','EXPORT_ALLOWED','EXPORT_COMPLETED','DOCUMENT_ALLOWED','DOCUMENT_COMPLETED','ASYNC_EFFECT_AUTHORIZED','ASYNC_REPLAY_AUTHORIZED','ASYNC_AUTHORIZATION_DENIED','ASYNC_JOB_OBSERVED','ASYNC_RECONCILIATION_REQUIRED','DOCUMENT_UPLOAD_INTENT_ACCEPTED','DOCUMENT_UPLOAD_CONFIRMED','DOCUMENT_SCAN_COMPLETED','DOCUMENT_ACCESS_CAPABILITY_ISSUED','DOCUMENT_VERSION_CREATED','DOCUMENT_ACCESS_BLOCKED','DOCUMENT_RECONCILIATION_DETECTED','DOCUMENT_UPLOAD_CANCELLED','DOCUMENT_LIFECYCLE_REQUESTED','OPPORTUNITY_CREATED','OPPORTUNITY_REVISION_CREATED','OPPORTUNITY_ARCHIVED','OPPORTUNITY_RESTORED','OPPORTUNITY_PROVENANCE_LINKED','OPPORTUNITY_QUALITY_EVALUATED','OPPORTUNITY_EXACT_DUPLICATE_IDENTIFIED','OPPORTUNITY_DUPLICATE_CANDIDATE_IDENTIFIED','OPPORTUNITY_DUPLICATE_DECISION_RECORDED','OPPORTUNITY_ACCESS_DENIED','OPPORTUNITY_RECONCILIATION_REQUIRED'));
ALTER TABLE audit.event DROP CONSTRAINT event_event_code_check; ALTER TABLE audit.event ADD CONSTRAINT event_event_code_check CHECK(event_code IN ('AUTHORIZATION_ALLOWED','AUTHORIZATION_DENIED','AUTHORIZATION_POLICY_INVALID','AUTHORIZATION_MFA_REQUIRED','AUTHORIZATION_VERSION_ADVANCED','GRANT_CHANGED','PROFILE_CHANGED','SOD_CHANGED','SENSITIVE_ACTION_ALLOWED','SUPPORT_GRANTED','SUPPORT_STARTED','SUPPORT_USED','SUPPORT_REVOKED','SUPPORT_EXPIRED','SERVICE_JOB_DISPATCHED','SERVICE_JOB_COMPLETED','EXPORT_ALLOWED','EXPORT_COMPLETED','ASYNC_EFFECT_AUTHORIZED','ASYNC_REPLAY_AUTHORIZED','ASYNC_AUTHORIZATION_DENIED','ASYNC_JOB_OBSERVED','ASYNC_RECONCILIATION_REQUIRED','DOCUMENT_UPLOAD_INTENT_ACCEPTED','DOCUMENT_UPLOAD_CONFIRMED','DOCUMENT_SCAN_COMPLETED','DOCUMENT_ACCESS_CAPABILITY_ISSUED','DOCUMENT_VERSION_CREATED','DOCUMENT_ACCESS_BLOCKED','DOCUMENT_RECONCILIATION_DETECTED','DOCUMENT_UPLOAD_CANCELLED','DOCUMENT_LIFECYCLE_REQUESTED','OPPORTUNITY_CREATED','OPPORTUNITY_REVISION_CREATED','OPPORTUNITY_ARCHIVED','OPPORTUNITY_RESTORED','OPPORTUNITY_PROVENANCE_LINKED','OPPORTUNITY_QUALITY_EVALUATED','OPPORTUNITY_EXACT_DUPLICATE_IDENTIFIED','OPPORTUNITY_DUPLICATE_CANDIDATE_IDENTIFIED','OPPORTUNITY_DUPLICATE_DECISION_RECORDED','OPPORTUNITY_ACCESS_DENIED','OPPORTUNITY_RECONCILIATION_REQUIRED'));
ALTER TABLE audit.event DROP CONSTRAINT event_catalog_version_check; ALTER TABLE audit.event ADD CONSTRAINT event_catalog_version_check CHECK(catalog_version IN ('f7-events-v1','f11-events-v2','f12-events-v2'));
